def maxPathSum(root) -> int:
    if not root:
        return 0

    # Handle tree list array representation directly
    if isinstance(root, list):
        if not root:
            return 0
        nodes = [TreeNode(x) if x is not None else None for x in root]
        for i in range(len(nodes)):
            if nodes[i]:
                l_idx = 2 * i + 1
                r_idx = 2 * i + 2
                if l_idx < len(nodes):
                    nodes[i].left = nodes[l_idx]
                if r_idx < len(nodes):
                    nodes[i].right = nodes[r_idx]
        root = nodes[0]

    res = [float("-inf")]

    def dfs(node):
        if not node:
            return 0
        left_max = max(dfs(node.left), 0)
        right_max = max(dfs(node.right), 0)
        res[0] = max(res[0], node.val + left_max + right_max)
        return node.val + max(left_max, right_max)

    dfs(root)
    return res[0]

